#!/bin/bash
# S247 stage 2 (MEDIATE): agxlog-s247-guest-test.sh with the g247B HV (J274 Hwdata profile), the
# fw-agx-s247 test payload (S237 + J274 AGX0 SSDT + AGX local reserve in PEI) and NWOAS_AGX_MODE=mediate.
# Generated by nwoas_scripts/fw-agx-s247/tools/make_agxmed_launcher.py. Pass/fail lines:
# port-j274/gpu/hv/README-hv2.md "2단계 로그 판정". HARDWARE-UNVERIFIED.
# Without the J274 GPU driver installed, Windows must boot exactly like stage 1.
# S244: display-s243-guest-test.sh for macOS 13.5 OS firmware (stub entry, iBoot-8422.141.2) with D4 m1n1.
# Same HV (S233b), payload (S237) and -m modules as S243. Changes (display-s244/README.md):
#   - Tahoe DCP hook + hpd_wait pins removed: on 13.5, D4 / S233b / guest m1n1 run m1n1's own display_init().
#   - display-s244/probe_fw135_s244.py gates BEFORE chainload (D4 identity, 13.5 OS FW, layout checks).
#   - display-s244/fw135_preflight.py replaces the hook as --pre-init-script (read-only, aborts before hv.init).
# HARDWARE-UNVERIFIED. Needs the GptGuard update first (stub-135 step 9), or layout-s231 GptGuard stops.
# Optional host->guest artifact delivery chosen at launch (nothing delivered when unset):
#   NWOAS_DELIVER_MANIFEST=<manifest.json>   (file-delivery-s243/s243_manifest.py create)
#   NWOAS_DELIVER_FILE=<file> NWOAS_DELIVER_SHA256=<hex>   (single file)
# The module appends NWGET243.EXE to the NS2 RAM FAT and serves artifacts on NS2 LBA127/129-144 only.
# Guest jobs: file-delivery-s243/make_job.py. Build alone is not hardware validation.
set -eu
ROOT=/Users/angigyeom/Desktop/DEV/NWOAS
M1N1="$ROOT/m1n1_windows"
DEV=/dev/cu.usbmodemC07HL05SQ6NY1
VUART=/dev/cu.usbmodemC07HL05SQ6NY3
PY="$M1N1/.venv-hv/bin/python3"
HV="/Users/angigyeom/Desktop/DEV/NWOAS/port-j274/gpu/hv/out-hv2/m1n1-g247B-agx-hv2-j274hwdata.bin"
AGXMOD="$ROOT/port-j274/gpu/hv/tools-hv2/agx_hv2_module.py"
export NWOAS_AGX_MODE=mediate
# 384 MiB AGX local reserve (identity guest RAM, region-id-24; README-hv2.md); Mu reserves it in PEI.
export NWOAS_AGX_LOCAL_IPA=0xa00000000
# J274 has no gpu-perf-base-pstate in the ADT; Asahi t8103-j274.dts: apple,perf-base-pstate = <3>.
export NWOAS_AGX_BASE_PSTATE=3
export NWOAS_AGX_SCANOUT_INTID=889 NWOAS_AGX_POOL_IPA=0xd00000000
PAYLOAD="/Users/angigyeom/Desktop/DEV/NWOAS/nwoas_scripts/fw-agx-s247/out/s247/m1n1-payload-s247-agx.bin"
LOG=$(mktemp "$ROOT/nwoas_scripts/logs/agxmedp-s247-$(date '+%Y%m%d-%H%M%S').XXXXXX")
S244="$ROOT/nwoas_scripts/display-s244"

export NWOAS_HV_READ_TIMEOUT=30
export M1N1DEVICE="$DEV" M1N1_KEEP_BAUD=1 M1N1_SPLIT_CONSOLE=1 PYTHONDONTWRITEBYTECODE=1
export PYTHONPATH="$M1N1/proxyclient:$ROOT/nwoas_scripts"
export NWOAS_LINK_DIR="$LOG.link"
export NWOAS_CONTROLLER_DIR="$ROOT/nwoas_scripts/nvme-s139"
export NWOAS_CPU_PSTATE=7 NWOAS_LATE_P12=0 NWOAS_DELIVER_CINEBENCH=0
export NWOAS_MAX_TRANSFER=1048576 NWOAS_NVME_FAST_MASK=1 NWOAS_TARGET_QUERY=1
export NWOAS_EXCLUDE_WINDOW=1 NWOAS_WIN_BASE=0 NWOAS_WIN_SIZE=0x100000000 NWOAS_LOG="$LOG"
export NWOAS_DCP_LOG="$LOG.dcp" NWOAS_HV_IMAGE="$HV"

echo "Log: $LOG"
[ -e "$DEV" ] || { echo 'STOP: direct CDC proxy missing'; exit 1; }
[ -e "$VUART" ] || { echo 'STOP: direct CDC diagnostic pipe missing'; exit 1; }
[ "$(stat -f %z "$HV")" -eq 2260992 ]
[ "$(shasum -a 256 "$HV" | awk '{print $1}')" = 2d70d7f15ee405235b8d0141d6d1ebf16a1f83b2d68963c226e4f9fec890c20e ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/layout-s231/guest_module.py" | awk '{print $1}')" = 07523c1d282a3d54bdcad1cbc9ea8d7b0a4fbf1d139387bb54b576c72b36dc03 ]
[ "$(stat -f %z "$PAYLOAD")" -eq 33669120 ]
[ "$(shasum -a 256 "$PAYLOAD" | awk '{print $1}')" = fb2011f96aea4ca30c69d5bd706a379a04010dc7895366b5c86e191444ee641c ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/native-s230/query_module.py" | awk '{print $1}')" = af4eeb7f45aa9669c264d2e3520ae3d79da4020c89354e85738989c55f80f09b ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/cpufreq-s193/capture.py" | awk '{print $1}')" = 6fa2119c02cbcfca71c0d76c235abd0ceb91ea1e295a11d6ffdc268f6c51c494 ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/memory-s180/link_module.py" | awk '{print $1}')" = 2c1db6cbbe2d7db5aca6f917af23a91c53c363e6b3480579062b723f9e9fb035 ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/file-upload-s169/client/NWPUT.EXE" | awk '{print $1}')" = 9789268cc68311776c8f80fe8f10e6503ccc56b3a5b902a40d8546c39383985b ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/file-delivery-s168/module.py" | awk '{print $1}')" = a2d57c1aa91fd239b1508775dd7d479ec489de4c3d4ef8f078751b79d64bb5e1 ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/file-delivery-s168/channel.py" | awk '{print $1}')" = 365123769a2d87b02cc024f9061df580c01184017b3fb494dd289384b74a02e9 ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/file-delivery-s168/adapter.py" | awk '{print $1}')" = ff67e437d68f460c4a9b0759bfdfaf7a5134f4ae00218ad34f47049e91061869 ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/file-delivery-s168/client/NWOAS-S168.EXE" | awk '{print $1}')" = 1b40db539c222cd80c29cb03149e0f5d5a010848203914272eaee77434d895d9 ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/cpufreq-s164/pstate12.py" | awk '{print $1}')" = caa2c29449b721d1000ac76e2c884387a75a079d381e7658e492817e7e3b25d2 ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/cpufreq-s189/observe.py" | awk '{print $1}')" = 03acf96337939fce01bdf614000c361ba7d3e68d3a865e7c945495d093f762fa ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/bench-session-s176/USERCB.EXE" | awk '{print $1}')" = 7e31d3e69d316232d3f934408367ca2824cd2acad2531a6de44133f06c056ecd ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/bench-session-s176/CBRUN.CMD" | awk '{print $1}')" = dfd1cde563fa3849ed6464ab8e49801ae4cd006755390451a21734fe80bfc465 ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/worker-s177/NWOS.EXE" | awk '{print $1}')" = 14a1c914cd54f122a6899d3ae784c290bea641dadc4378883a150abc80db1b7f ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/memory-s180/memtest/MEMTEST.EXE" | awk '{print $1}')" = ce9303eb00c0ddca980e7df58008423913065e689b31870154d50c37933442b4 ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/usb-s174/guest_map.py" | awk '{print $1}')" = 2477172728d5554c4b2a07488e42f956cfd2e7a78e70a15c2d7a1488bf5656c0 ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/layout-s231/module.py" | awk '{print $1}')" = cce19a6c3ef3e06be61482efa02743e10cbb2cd9cf18d9e15e3f8f48ab0e2004 ]
[ "$(shasum -a 256 "$AGXMOD" | awk '{print $1}')" = 7af920a668e0c9459017707951f049362649ba284860f70ba2eebd4bd52dcdb9 ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/file-delivery-s243/module.py" | awk '{print $1}')" = f53939c89250ecff5fe0deefe2f60211c0a8d9ad9ae5811d2741a5243cdb36d7 ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/file-delivery-s243/s243_channel.py" | awk '{print $1}')" = c2e8b0e6330260e756b49fdf8e1d42f39d9d51cb0cd56d3671071fa34d338714 ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/file-delivery-s243/s243_adapter.py" | awk '{print $1}')" = a0dab3c091ec862e26765ff0f66170b083aa20222f4903dac73e0509336d6ee9 ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/file-delivery-s243/s243_fat.py" | awk '{print $1}')" = d72caa126fbb66cc06dc02d8122a71818e375ed1a047003162ea6b72978638d9 ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/file-delivery-s243/s243_manifest.py" | awk '{print $1}')" = 29a86b8a51cb46adf736c7e8bcc5dd6b5f2edb4974560afce8f46e2d1bed6ec9 ]
[ "$(shasum -a 256 "$ROOT/nwoas_scripts/file-delivery-s243/client/NWGET243.EXE" | awk '{print $1}')" = fc457722e1aa8e384385f6118a3719c86268cfb339497ddff218b0d113222f5b ]
if /usr/sbin/lsof -t "$DEV" "$VUART" >/dev/null 2>&1; then echo 'STOP: CDC pipe busy'; exit 1; fi
shasum -a 256 "$HV" "$PAYLOAD" "$ROOT/nwoas_scripts/cpufreq-s193/capture.py" \
    "$ROOT/nwoas_scripts/nvme-s139/controller.py" >> "$LOG"
echo '[S244] S243 stack on 13.5 OS firmware: no Tahoe DCP hook, m1n1-owned framebuffer, probe + preflight gates' | tee -a "$LOG"
echo "[S244] delivery: MANIFEST=${NWOAS_DELIVER_MANIFEST:-} FILE=${NWOAS_DELIVER_FILE:-} SHA256=${NWOAS_DELIVER_SHA256:-}" | tee -a "$LOG"
[ -z "${NWOAS_DELIVER_MANIFEST:-}" ] || shasum -a 256 "$NWOAS_DELIVER_MANIFEST" >> "$LOG"

[ "$(shasum -a 256 "$S244/fw135_model.py" | awk '{print $1}')" = ed7b7857dc2cafe6d5a7a2dc40122ba2c93e4d702361d83bb70104e287c26e89 ]
[ "$(shasum -a 256 "$S244/fw135_preflight.py" | awk '{print $1}')" = d66b576bebc355541419ec17bca324d5c9f26e14db8c5f7fde931605dbb6a398 ]
[ "$(shasum -a 256 "$S244/probe_fw135_s244.py" | awk '{print $1}')" = f456c3283d5a68e42d7fb323ea08111ada58380af332fc84533f12e5bf5fbd4b ]
[ "$(md5 -q "$ROOT/experiments/tahoe-afk-20260906/m1n1-dcp-defer.bin")" = 7bec0225edc101857be3b7f195dd7357 ]
VUART_PID=
cleanup() {
    if [ -n "$VUART_PID" ]; then
        kill "$VUART_PID" >/dev/null 2>&1 || true
        wait "$VUART_PID" >/dev/null 2>&1 || true
    fi
}
trap cleanup EXIT HUP TERM
trap ':' INT

"$PY" -u "$ROOT/nwoas_scripts/recovery-s126/proxy_ready.py" >> "$LOG" 2>&1
# S244 gate (read-only, on D4, before anything is chainloaded): exit 0 required.
PROBE_RC=0
"$PY" -B -u "$S244/probe_fw135_s244.py" > "$LOG.probe" 2>&1 || PROBE_RC=$?
cat "$LOG.probe" >> "$LOG"
grep -a '^\[S244-probe\]' "$LOG.probe" || true
[ "$PROBE_RC" -eq 0 ] || { echo "STOP: S244 probe exit $PROBE_RC (1=not 13.5, 2=proxy, 3=not D4, 4=layout); nothing chainloaded"; exit 1; }
"$PY" -u "$M1N1/proxyclient/tools/chainload.py" -r "$HV" >> "$LOG" 2>&1
grep -qa 'Proxy is alive again\|WARNING: chainload confirm' "$LOG" || exit 2
"$PY" -u "$ROOT/nwoas_scripts/baud-s144/capture_vuart.py" \
    --port "$VUART" --output "$LOG.vuart" --ignore-sigint &
VUART_PID=$!

"$PY" -u "$M1N1/proxyclient/tools/run_guest.py" -r --strict-init \
    --pre-init-script "$S244/fw135_preflight.py" \
    -m "$ROOT/nwoas_scripts/cpufreq-s193/capture.py" \
    -m "$ROOT/nwoas_scripts/usb-s174/guest_map.py" \
    -m "$ROOT/nwoas_scripts/smp-s133/pmgr_gate.py" \
    -m "$ROOT/nwoas_scripts/layout-s231/guest_module.py" \
    -m "$ROOT/nwoas_scripts/memory-s180/link_module.py" \
    -m "$ROOT/nwoas_scripts/file-delivery-s243/module.py" \
    -m "$ROOT/nwoas_scripts/layout-s231/module.py" \
    -m "$AGXMOD" \
    -m "$ROOT/nwoas_scripts/native-s230/query_module.py" \
    -m "$ROOT/nwoas_scripts/cpufreq-s189/observe.py" "$PAYLOAD" >> "$LOG" 2>&1
